\
uip maestro flow node configure "CeqlWhereTest.flow" "listAadGroups1" --detail "$(cat <<'JSON'
{
  "connectionId": "26b7ac14-424a-45ae-88ee-88ae5c8794ce",
  "folderKey": "5da18ec0-7de1-4e57-aaf1-ddc8a369c199",
  "method": "GET",
  "endpoint": "/groups",
  "objectName": "groups",
  "filter": {
    "groupOperator": 0,
    "index": 0,
    "filters": [
      {
        "id": "displayName",
        "operator": "Equals",
        "value": {
          "value": "active",
          "rawString": "\"active\"",
          "isLiteral": true
        }
      }
    ],
    "groups": []
  }
}
JSON
)" --output json 2>/dev/null

